#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    // Closed interval [x-r, x+r] on integers: +1 at x-r, -1 at x+r+1.
    vector<pair<long long, int>> ev;
    ev.reserve(2 * n);
    for (int i = 0; i < n; i++) {
        long long x, r;
        scanf("%lld %lld", &x, &r);
        ev.push_back({x - r, 1});
        ev.push_back({x + r + 1, -1});
    }
    sort(ev.begin(), ev.end());
    long long count = 0, best = 0, ans = 0;
    for (size_t i = 0; i < ev.size();) {
        size_t j = i;
        long long pos = ev[i].first;
        while (j < ev.size() && ev[j].first == pos) count += ev[j++].second;
        if (count > best) { best = count; ans = pos; }  // strict: keep the leftmost tie
        i = j;
    }
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.Arrays;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Closed interval [x-r, x+r] on integers: +1 at x-r, -1 at x+r+1.
        // Encode each event as position*2 + (1 for +1, 0 for -1); merging per position makes the order irrelevant.
        long[] key = new long[2 * n];
        for (int i = 0; i < n; i++) {
            long x = nextLong(), r = nextLong();
            key[2 * i] = (x - r) * 2 + 1;
            key[2 * i + 1] = (x + r + 1) * 2;
        }
        Arrays.sort(key);
        long count = 0, best = 0, ans = 0;
        for (int i = 0; i < 2 * n;) {
            long p = Math.floorDiv(key[i], 2);
            int j = i;
            while (j < 2 * n && Math.floorDiv(key[j], 2) == p) {
                count += Math.floorMod(key[j], 2) == 1 ? 1 : -1;
                j++;
            }
            if (count > best) { best = count; ans = p; }  // strict: keep the leftmost tie
            i = j;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

type event struct{ pos, delta int }

func main() {
	n := readInt()
	// Closed interval [x-r, x+r] on integers: +1 at x-r, -1 at x+r+1.
	ev := make([]event, 0, 2*n)
	for i := 0; i < n; i++ {
		x, r := readInt(), readInt()
		ev = append(ev, event{x - r, 1}, event{x + r + 1, -1})
	}
	sort.Slice(ev, func(a, b int) bool { return ev[a].pos < ev[b].pos })
	count, best, ans := 0, 0, 0
	for i := 0; i < len(ev); {
		j, p := i, ev[i].pos
		for j < len(ev) && ev[j].pos == p {
			count += ev[j].delta
			j++
		}
		if count > best { // strict: keep the leftmost tie
			best, ans = count, p
		}
		i = j
	}
	fmt.Println(ans)
}
